(function(){
  // ---------- Setup ----------
  var wrap = document.getElementById('canvas-wrap');
  var scene = new THREE.Scene();
  scene.fog = new THREE.Fog(0x141210, 10, 42);
  var camera = new THREE.PerspectiveCamera(55, innerWidth/innerHeight, 0.1, 100);
  var renderer = new THREE.WebGLRenderer({antialias:true, alpha:false});
  renderer.setSize(innerWidth, innerHeight);
  renderer.setPixelRatio(Math.min(devicePixelRatio,2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  wrap.appendChild(renderer.domElement);

  window.addEventListener('resize', function(){
    camera.aspect = innerWidth/innerHeight; camera.updateProjectionMatrix();
    renderer.setSize(innerWidth, innerHeight);
  });

  // ---------- Materials / helpers ----------
  function canvasTexture(colors, seed){
    var c = document.createElement('canvas'); c.width=256; c.height=320;
    var ctx = c.getContext('2d');
    var g = ctx.createLinearGradient(0,0,256,320);
    g.addColorStop(0, colors[0]); g.addColorStop(.55, colors[1]); g.addColorStop(1, colors[2]);
    ctx.fillStyle = g; ctx.fillRect(0,0,256,320);
    var rnd = seed;
    function r(){ rnd = (rnd*9301+49297)%233280; return rnd/233280; }
    ctx.globalAlpha = .35;
    for(var i=0;i<40;i++){
      ctx.fillStyle = colors[i%2];
      var x=r()*256, y=r()*320, s=r()*60+10;
      ctx.beginPath(); ctx.arc(x,y,s,0,Math.PI*2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    var t = new THREE.CanvasTexture(c); return t;
  }

  var floorMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.55, metalness:.05});
  var wallMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.9});
  var frameMat = new THREE.MeshStandardMaterial({color:0xd4af52, roughness:.32, metalness:.75});
  var moldingMat = new THREE.MeshStandardMaterial({color:0xe9e2cf, roughness:.5});

  // ---------- Procedural surface textures (no external images needed) ----------
  function grainCanvas(w,h,base,options){
    var c = document.createElement('canvas'); c.width=w; c.height=h;
    var ctx = c.getContext('2d');
    ctx.fillStyle = base; ctx.fillRect(0,0,w,h);
    var img = ctx.getImageData(0,0,w,h), d = img.data;
    for(var i=0;i<d.length;i+=4){
      var n = (Math.random()-0.5) * options.noise;
      d[i]+=n; d[i+1]+=n; d[i+2]+=n;
    }
    ctx.putImageData(img,0,0);
    return {c:c, ctx:ctx};
  }
  function makeMarble(w,h){
    var g = grainCanvas(w,h,'#c7bfae',{noise:8});
    var ctx = g.ctx;
    ctx.globalAlpha = .05;
    for(var i=0;i<250;i++){
      ctx.fillStyle = Math.random()>0.5 ? '#d8d0bf' : '#b3a996';
      var r=Math.random()*24+6;
      ctx.beginPath(); ctx.arc(Math.random()*w, Math.random()*h, r, 0, Math.PI*2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    return g.c;
  }
  function makeOakFloor(w,h){
    var c = document.createElement('canvas'); c.width=w; c.height=h;
    var ctx = c.getContext('2d');
    var planks = 8, pw = w/planks;
    var tones = ['#b98a54','#c9a06a','#a97a48','#d1a874','#bb8f5c','#c4986a'];
    for(var p=0;p<planks;p++){ ctx.fillStyle = tones[p%tones.length]; ctx.fillRect(p*pw,0,pw,h); }
    ctx.strokeStyle = 'rgba(35,20,8,0.4)'; ctx.lineWidth = 2;
    for(var p=0;p<=planks;p++){ ctx.beginPath(); ctx.moveTo(p*pw,0); ctx.lineTo(p*pw,h); ctx.stroke(); }
    ctx.strokeStyle = 'rgba(60,35,15,0.15)';
    for(var i=0;i<160;i++){
      ctx.lineWidth = 0.5+Math.random();
      var y=Math.random()*h;
      ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y+(Math.random()-0.5)*6); ctx.stroke();
    }
    return c;
  }
  function makeSkylight(w,h){
    var c = document.createElement('canvas'); c.width=w; c.height=h;
    var ctx = c.getContext('2d');
    ctx.fillStyle = '#cfe0ea'; ctx.fillRect(0,0,w,h);
    ctx.globalAlpha = .18;
    for(var i=0;i<30;i++){ ctx.fillStyle='#ffffff'; var r=Math.random()*40+10; ctx.beginPath(); ctx.arc(Math.random()*w,Math.random()*h,r,0,Math.PI*2); ctx.fill(); }
    ctx.globalAlpha = 1;
    ctx.strokeStyle = '#4a4438'; ctx.lineWidth = 4;
    var cells = 8;
    for(var i=0;i<=cells;i++){ var x=i*w/cells; ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,h); ctx.stroke(); }
    var rows = Math.round(cells*h/w);
    for(var j=0;j<=rows;j++){ var y=j*w/cells; ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y); ctx.stroke(); }
    return c;
  }
  function makeWoodGrain(w,h){
    var g = grainCanvas(w,h,'#3a2717',{noise:10});
    var ctx = g.ctx;
    for(var y=0;y<h;y+=4){
      ctx.strokeStyle = 'rgba(70,45,25,'+(0.18+Math.random()*0.22)+')';
      ctx.lineWidth = 1+Math.random()*1.5;
      ctx.beginPath(); ctx.moveTo(0,y+Math.random()*4);
      for(var x=0;x<=w;x+=40){ ctx.lineTo(x, y+(Math.random()-0.5)*6); }
      ctx.stroke();
    }
    return g.c;
  }
  function makeFabric(w,h){
    var g = grainCanvas(w,h,'#8f8577',{noise:10});
    var ctx = g.ctx;
    ctx.strokeStyle = 'rgba(60,55,46,0.12)'; ctx.lineWidth = 1;
    for(var i=0;i<w;i+=4){ ctx.beginPath(); ctx.moveTo(i,0); ctx.lineTo(i,h); ctx.stroke(); }
    for(var j=0;j<h;j+=4){ ctx.beginPath(); ctx.moveTo(0,j); ctx.lineTo(w,j); ctx.stroke(); }
    return g.c;
  }
  function makeStone(w,h){
    var g = grainCanvas(w,h,'#b8b0a0',{noise:12});
    var ctx = g.ctx;
    for(var i=0;i<14;i++){
      ctx.strokeStyle = 'rgba(140,132,116,'+(0.1+Math.random()*0.15)+')';
      ctx.lineWidth = 0.6+Math.random()*1.8;
      ctx.beginPath();
      var sx=Math.random()*w, sy=Math.random()*h;
      ctx.moveTo(sx,sy);
      ctx.quadraticCurveTo(sx+(Math.random()-0.5)*w*.4, sy+(Math.random()-0.5)*h*.4, sx+(Math.random()-0.5)*w*.6, sy+(Math.random()-0.5)*h*.6);
      ctx.stroke();
    }
    return g.c;
  }
  function makeTerracotta(w,h){
    var g = grainCanvas(w,h,'#a85a3c',{noise:12});
    var ctx = g.ctx;
    ctx.strokeStyle = 'rgba(70,32,18,0.25)'; ctx.lineWidth = 3;
    for(var y=0;y<h;y+=18){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y); ctx.stroke(); }
    return g.c;
  }
  function makeLeafTex(w,h){
    var g = grainCanvas(w,h,'#38512f',{noise:16});
    var ctx = g.ctx;
    ctx.globalAlpha = .2;
    for(var i=0;i<60;i++){ ctx.fillStyle = Math.random()>0.5?'#4d6b3f':'#243620'; var r=Math.random()*14+4; ctx.beginPath(); ctx.arc(Math.random()*w,Math.random()*h,r,0,Math.PI*2); ctx.fill(); }
    ctx.globalAlpha = 1;
    return g.c;
  }
  function makeRugPattern(w,h){
    var c = document.createElement('canvas'); c.width=w; c.height=h;
    var ctx = c.getContext('2d');
    ctx.fillStyle = '#5c1f1e'; ctx.fillRect(0,0,w,h);
    ctx.strokeStyle = '#c9a86a'; ctx.lineWidth = 10;
    ctx.strokeRect(16,16,w-32,h-32);
    ctx.lineWidth = 3;
    ctx.strokeRect(34,34,w-68,h-68);
    ctx.fillStyle = '#c9a86a';
    var cols=5, rows=7;
    for(var i=0;i<cols;i++){
      for(var j=0;j<rows;j++){
        var cx = 60 + i*(w-120)/(cols-1), cy = 60 + j*(h-120)/(rows-1);
        ctx.save(); ctx.translate(cx,cy); ctx.rotate(Math.PI/4);
        ctx.fillRect(-6,-6,12,12); ctx.restore();
      }
    }
    return c;
  }
  function tileTex(canvas, rx, ry){
    var t = new THREE.CanvasTexture(canvas);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(rx, ry);
    t.encoding = THREE.sRGBEncoding;
    t.anisotropy = 4;
    t.needsUpdate = true;
    return t;
  }
  var wallCanvas = makeMarble(512,512);
  var oakCanvas = makeOakFloor(512,512);
  var skylightCanvas = makeSkylight(512,128);
  var woodGrainCanvas = makeWoodGrain(256,256);
  var fabricCanvas = makeFabric(256,256);
  var stoneCanvas = makeStone(256,256);
  var terracottaCanvas = makeTerracotta(256,256);
  var leafCanvas = makeLeafTex(128,128);
  var rugCanvas = makeRugPattern(512,512);

  floorMat.map = tileTex(oakCanvas, 1, 16);
  floorMat.bumpMap = tileTex(oakCanvas, 1, 16);
  floorMat.bumpScale = 0.01;

  wallMat.map = tileTex(wallCanvas, 6, 2);
  wallMat.bumpMap = tileTex(wallCanvas, 6, 2);
  wallMat.bumpScale = 0.015;

  var skylightTex = tileTex(skylightCanvas, 1, 8);
  var ceilMat = new THREE.MeshStandardMaterial({map:skylightTex, emissive:0xffffff, emissiveMap:skylightTex, emissiveIntensity:0.55, roughness:1});
  floorMat.bumpScale = 0.015;

  var hallGroup = new THREE.Group(); scene.add(hallGroup);

  // Floor + walls (long corridor of galleries)
  var floor = new THREE.Mesh(new THREE.PlaneGeometry(14, 90), floorMat);
  floor.rotation.x = -Math.PI/2; floor.position.set(0,0,-30); floor.receiveShadow = true;
  hallGroup.add(floor);

  var wallL = new THREE.Mesh(new THREE.PlaneGeometry(90,7), wallMat);
  wallL.position.set(-7,3.5,-30); wallL.rotation.y = Math.PI/2; wallL.receiveShadow = true; hallGroup.add(wallL);
  var wallR = wallL.clone(); wallR.position.set(7,3.5,-30); wallR.rotation.y = -Math.PI/2; wallR.receiveShadow = true; hallGroup.add(wallR);
  var ceil = new THREE.Mesh(new THREE.PlaneGeometry(14,90), ceilMat);
  ceil.position.set(0,7,-30); ceil.rotation.x = Math.PI/2; hallGroup.add(ceil);

  // Crown molding, picture rail, baseboard on both walls
  function addMolding(xPos, side){
    var crown = new THREE.Mesh(new THREE.BoxGeometry(0.12,0.18,90), moldingMat);
    crown.position.set(xPos + side*0.06, 6.85, -30); hallGroup.add(crown);
    var rail = new THREE.Mesh(new THREE.BoxGeometry(0.06,0.08,90), moldingMat);
    rail.position.set(xPos + side*0.03, 5.55, -30); hallGroup.add(rail);
    var base = new THREE.Mesh(new THREE.BoxGeometry(0.14,0.3,90), moldingMat);
    base.position.set(xPos + side*0.07, 0.15, -30); hallGroup.add(base);
  }
  addMolding(-7, 1);
  addMolding(7, -1);

  // ---------- Uploaded memory photos (base64-embedded, no external fetch needed) ----------
  var IMG_MET = "data:image/jpeg;base64,";
  var IMG_DATE = "data:image/jpeg;base64,";
  var IMG_GRAD = "data:image/jpeg;base64,";
  var IMG_FAM = "data:image/jpeg;base64,";
  var IMG_STUDY = "data:image/jpeg;base64,";
  var IMG_ORACION = "data:image/jpeg;base64,";

  // Artworks data (6 pieces across 2 galleries)
  var artworks = [
    {x:-6.85, z:-4, title:"When I First Met You", artist:"", date:"", desc:"", side:1, palette:['#8a5a2c','#c98a3f','#2c1a0c'],
      img: IMG_MET, ratio: 0.75,
      letter:"I still remember how surreal it felt to finally see you in person for the first time. It's strange how one moment can rearrange everything you thought you knew — because right then, something in me just knew you were my sure thing. I didn't want that feeling to be temporary. I still don't."},
    {x:6.85, z:-9, title:"Another Round", artist:"", date:"", desc:"", side:-1, palette:['#3b4a5c','#7d93a8','#101820'],
      img: IMG_DATE, ratio: 0.75,
      letter:"It's kind of funny looking back — our first date was short, just a few hours, and yet somehow we were already planning the next one before it even ended. I think that's when it hit me: whatever this was, it wasn't going to be easy to walk away from. We were already inseparable, even that early on."},
    {x:-6.85, z:-14, title:"Congrats to Graduating and Passing, My RN", artist:"", date:"", desc:"", side:1, palette:['#6b6a63','#c9c4b6','#232019'],
      img: IMG_GRAD, ratio: 0.75,
      letter:"Out of everything I've ever been proud of, nothing comes close to how proud I am of you. I watched how hard you worked to get here — the late nights, the stress, the doubts you tried to hide — and I want you to know I saw all of it. Seeing you walk across that stage was one of the best days of my life, second only to the day I met you."},
    {x:6.85, z:-19, title:"Being Close to Not Only You, But Your Family", artist:"", date:"", desc:"", side:-1, palette:['#7a2e1f','#d97757','#1c0d08'],
      img: IMG_FAM, ratio: 1.333,
      letter:"Ever since you introduced me to your family, I felt a kind of welcome I honestly didn't expect. The way they treat me like I already belong, like I'm one of them, means more to me than I probably show. I'll be forever grateful for that, and for you, for letting me in."},
    {x:-6.85, z:-24, title:"It's the Simple Things That Make It Memorable", artist:"", date:"", desc:"", side:1, palette:['#4a4238','#8c8168','#161310'],
      img: IMG_STUDY, ratio: 1.333,
      letter:"We only planned to study that day, walang ibang agenda — and somehow it still turned into one of my favorite memories. It reminded me that it doesn't take a grand plan to make something unforgettable; it just takes you. Thank you din po sa treat, by the way. I still owe you one."},
    {x:6.85, z:-29, title:"Welcome to the Oracion Family", artist:"", date:"", desc:"", side:-1, palette:['#2c3b3a','#5fa89e','#0c1514'],
      img: IMG_ORACION, ratio: 0.75,
      letter:"This day had been a long time coming, and I'm so glad it finally happened, just like I promised. I hope you felt at home with my family, because they already love you the way I do, maybe even more. Welcome to the Oracion family — you've been part of it for a while now, even before it was official."}
  ];

  var texLoader = new THREE.TextureLoader();
  var FRAME_MAX_W = 1.9, FRAME_MAX_H = 2.4, FRAME_BORDER = 0.3;
  artworks.forEach(function(a, i){
    var mat = new THREE.MeshStandardMaterial({roughness:.55, emissive:0x000000, emissiveIntensity:0});
    if(a.img){
      var tex = texLoader.load(a.img);
      tex.encoding = THREE.sRGBEncoding;
      mat.map = tex;
    } else {
      var ctex = canvasTexture(a.palette, i*17+3);
      ctex.encoding = THREE.sRGBEncoding;
      mat.map = ctex;
    }
    // size the frame to the photo's own aspect ratio instead of forcing a fixed shape
    var ratio = a.ratio || 0.75;
    var frameW, frameH;
    if(ratio >= FRAME_MAX_W/FRAME_MAX_H){ frameW = FRAME_MAX_W; frameH = FRAME_MAX_W/ratio; }
    else { frameH = FRAME_MAX_H; frameW = FRAME_MAX_H*ratio; }
    var artW = frameW - FRAME_BORDER, artH = frameH - FRAME_BORDER;

    var art = new THREE.Mesh(new THREE.PlaneGeometry(artW, artH), mat);
    var frame = new THREE.Mesh(new THREE.BoxGeometry(frameW, frameH, .08), frameMat);
    frame.position.set(a.x + (a.side*0.05), 3, a.z);
    frame.rotation.y = a.side>0 ? Math.PI/2 : -Math.PI/2;
    art.position.copy(frame.position); art.position.x += a.side*0.05;
    art.rotation.copy(frame.rotation);
    frame.castShadow = true; frame.receiveShadow = true;
    art.castShadow = true; art.receiveShadow = true;
    hallGroup.add(frame); hallGroup.add(art);

    var spot = new THREE.SpotLight(0xffefd2, 1.5, 12, Math.PI/5, .55, 1.3);
    spot.position.set(a.x - a.side*1.2, 6, a.z);
    spot.target.position.copy(frame.position);
    spot.castShadow = true;
    spot.shadow.mapSize.set(1024,1024);
    spot.shadow.camera.near = 1; spot.shadow.camera.far = 14;
    spot.shadow.bias = -0.0018; spot.shadow.radius = 3;
    hallGroup.add(spot); hallGroup.add(spot.target);
    a.spot = spot;
    a.mesh = frame;
    a.artMesh = art;
  });

  // ---------- Decorations: benches, pedestals, plants, rugs ----------
  var benchMat2 = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.7});
  benchMat2.map = tileTex(fabricCanvas, 2, 1);
  var woodLegMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.5});
  woodLegMat.map = tileTex(woodGrainCanvas, 1, 1);
  var pedestalMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.4});
  pedestalMat.map = tileTex(stoneCanvas, 1, 1);
  var sculptMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.3, metalness:.15});
  sculptMat.map = tileTex(stoneCanvas, 1, 1);
  var potMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.75});
  potMat.map = tileTex(terracottaCanvas, 1, 1);
  var leafMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.8});
  leafMat.map = tileTex(leafCanvas, 1, 1);
  var rugMat = new THREE.MeshStandardMaterial({color:0xffffff, roughness:.95});
  rugMat.map = tileTex(rugCanvas, 1, 1);

  function addBench(x, z, rotY){
    var g = new THREE.Group();
    var seat = new THREE.Mesh(new THREE.BoxGeometry(1.8,.12,.6), benchMat2);
    seat.position.y = .42; g.add(seat);
    [[-.75,-.2],[ .75,-.2],[-.75,.2],[.75,.2]].forEach(function(p){
      var leg = new THREE.Mesh(new THREE.BoxGeometry(.08,.42,.08), woodLegMat);
      leg.position.set(p[0],.21,p[1]); g.add(leg);
    });
    g.position.set(x,0,z); g.rotation.y = rotY||0;
    g.traverse(function(o){ if(o.isMesh){ o.castShadow=true; o.receiveShadow=true; }});
    hallGroup.add(g);
  }

  function addPedestal(x, z, shape){
    var g = new THREE.Group();
    var base = new THREE.Mesh(new THREE.CylinderGeometry(.28,.32,1.0,20), pedestalMat);
    base.position.y = .5; g.add(base);
    var s;
    if(shape===0) s = new THREE.Mesh(new THREE.SphereGeometry(.24,20,16), sculptMat);
    else if(shape===1) s = new THREE.Mesh(new THREE.TorusGeometry(.2,.08,12,24), sculptMat);
    else s = new THREE.Mesh(new THREE.ConeGeometry(.22,.42,24), sculptMat);
    s.position.y = 1.22; g.add(s);
    g.position.set(x,0,z);
    g.traverse(function(o){ if(o.isMesh){ o.castShadow=true; o.receiveShadow=true; }});
    hallGroup.add(g);
  }

  function addPlant(x, z){
    var g = new THREE.Group();
    var pot = new THREE.Mesh(new THREE.CylinderGeometry(.26,.2,.42,16), potMat);
    pot.position.y = .21; g.add(pot);
    for(var i=0;i<5;i++){
      var leaf = new THREE.Mesh(new THREE.ConeGeometry(.22,1.0,8), leafMat);
      leaf.position.set((Math.random()-0.5)*.25, .9+Math.random()*.25, (Math.random()-0.5)*.25);
      leaf.rotation.z = (Math.random()-0.5)*.5; leaf.rotation.x = (Math.random()-0.5)*.3;
      g.add(leaf);
    }
    g.position.set(x,0,z);
    g.traverse(function(o){ if(o.isMesh){ o.castShadow=true; o.receiveShadow=true; }});
    hallGroup.add(g);
  }

  function addRug(x, z, w, d){
    var rug = new THREE.Mesh(new THREE.PlaneGeometry(w,d), rugMat);
    rug.rotation.x = -Math.PI/2; rug.position.set(x,.005,z);
    rug.receiveShadow = true; hallGroup.add(rug);
  }

  addRug(0, -1, 3.4, 4.2);
  addBench(0, -1, Math.PI/2);
  addPedestal(-3.1, -6.5, 0);
  addPedestal(3.1, -11.5, 1);
  addPlant(-3.3, -1.5);
  addPlant(3.3, -16.5);
  addPlant(-3.3, -21.5);
  addRug(0, -26, 3.0, 5);
  addBench(0, -26, Math.PI/2);
  addPedestal(-3.1, -26, 2);
  addPlant(3.3, -31.5);
  addPlant(-1.8, -35.5);

  // Empty final room + single empty frame + bench
  var farZ = -37;
  var benchMat = new THREE.MeshStandardMaterial({color:0x3a2f22, roughness:.7});
  var bench = new THREE.Mesh(new THREE.BoxGeometry(2.4,.4,.6), benchMat);
  bench.position.set(0,.2,farZ); bench.castShadow = true; bench.receiveShadow = true; hallGroup.add(bench);
  var emptyFrame = new THREE.Mesh(new THREE.BoxGeometry(1.9,2.4,.08), frameMat);
  emptyFrame.position.set(0,3,farZ-4); emptyFrame.castShadow = true; emptyFrame.receiveShadow = true; hallGroup.add(emptyFrame);

  // Lighting
  var amb = new THREE.AmbientLight(0x9a917d, 0.65); scene.add(amb);
  var hemi = new THREE.HemisphereLight(0xcfe0ea, 0x2a2418, 0.55); scene.add(hemi);

  // General corridor fill lights so the space between artworks isn't dark
  for(var cz=4; cz>-40; cz-=6){
    var fill = new THREE.PointLight(0xfff3dd, .35, 11);
    fill.position.set(0, 6.4, cz);
    hallGroup.add(fill);
  }

  // ---------- Camera path ----------
  var path = [
    {p:[0,1.6,6],  l:[0,2,0]},
    {p:[0,1.6,0],  l:[0,2,-4]},
    {p:[-2,1.7,-6], l:[-6.85,3,-4]},
    {p:[2,1.7,-11], l:[6.85,3,-9]},
    {p:[-2,1.7,-16], l:[-6.85,3,-14]},
    {p:[2,1.7,-21], l:[6.85,3,-19]},
    {p:[-2,1.7,-26], l:[-6.85,3,-24]},
    {p:[2,1.7,-31], l:[6.85,3,-29]},
    {p:[0,1.6,-36], l:[0,2,farZ-4]},
    {p:[0,1.6,-40], l:[0,2,farZ-8]}
  ];
  function lerpV(a,b,t){ return [a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t]; }
  function cameraAt(t){
    t = Math.min(Math.max(t,0),1);
    var n = path.length-1;
    var f = t*n, i = Math.min(Math.floor(f), n-1), lt = f - i;
    var p = lerpV(path[i].p, path[i+1].p, lt);
    var l = lerpV(path[i].l, path[i+1].l, lt);
    return {p:p,l:l};
  }

  // ---------- Scroll state ----------
  var DOC_LEN = 9000; // px of scrollable content -> proportion to number of scenes
  document.getElementById('scroll-spacer').style.height = DOC_LEN + 'px';
  var scrollT = 0, targetT = 0;
  var galleryEnd = 0.62;   // museum portion ends
  var blackStart = 0.66, blackEnd = 0.72;
  var msgWindows = [
    [0.73,0.78],[0.78,0.83],[0.83,0.88],[0.88,0.92],[0.92,0.96]
  ];
  var questionAt = 0.965, buttonsAt = 0.985;

  var heroEl = document.getElementById('hero');
  var heroTitle = heroEl.querySelector('.hero-title');
  var heroSub = heroEl.querySelector('.hero-sub');
  var introVeil = document.getElementById('intro-veil');
  var introDone = false;
  var plaqueEl = document.getElementById('plaque');
  var veilEl = document.getElementById('black-veil');
  var msgLayer = document.getElementById('message-layer');
  var lines = ['m1','m2','m3','m4','m5'].map(function(id){return document.getElementById(id);});
  var questionEl = document.getElementById('question');
  var buttonsEl = document.getElementById('buttons');
  var finalMsgEl = document.getElementById('final-msg');
  var scrollHint = document.getElementById('scroll-hint');

  function startIntro(){
    setTimeout(function(){
      if(heroTitle) heroTitle.classList.add('show');
    }, 250);

    setTimeout(function(){
      if(heroSub) heroSub.classList.add('show');
    }, 850);

    setTimeout(function(){
      if(introVeil) introVeil.classList.add('hidden');
    }, 2400);

    setTimeout(function(){
      introDone = true;
      if(scrollT < 0.04) scrollHint.classList.add('show');
    }, 3800);
  }

  function finishIntroQuickly(){
    if(!introDone){
      introDone = true;
      if(heroTitle) heroTitle.classList.add('show');
      if(heroSub) heroSub.classList.add('show');
      if(introVeil) introVeil.classList.add('hidden');
      if(scrollT < 0.04) scrollHint.classList.add('show');
    }
  }

  var scrollContainer = document.getElementById('scroll-container');
  scrollContainer.addEventListener('scroll', function(){
    var max = scrollContainer.scrollHeight - scrollContainer.clientHeight;
    targetT = max>0 ? (scrollContainer.scrollTop / max) : 0;
    if(targetT > 0.002) finishIntroQuickly();
  }, {passive:true});

  // ---------- Letter popups ----------
  var raycaster = new THREE.Raycaster();
  var ndc = new THREE.Vector2();
  var clickableMeshes = artworks.map(function(a){ return a.mesh; });
  var letterModal = document.getElementById('letter-modal');
  var letterTitle = document.getElementById('letter-title');
  var letterSub = document.getElementById('letter-sub');
  var letterBody = document.getElementById('letter-body');
  var letterImg = document.getElementById('letter-img');
  var letterPhotoWrap = document.getElementById('letter-photo-wrap');
  var tapHint = document.getElementById('tap-hint');

  function openLetter(a){
    letterTitle.textContent = a.title;
    var sub = (a.artist || a.date) ? (a.artist + (a.artist && a.date ? ' — ' : '') + a.date) : '';
    letterSub.textContent = sub;
    letterSub.style.display = sub ? 'block' : 'none';
    letterBody.textContent = a.letter;
    if(a.img && letterImg){
      letterImg.src = a.img;
      letterImg.alt = a.title || 'Memory photo';
      if(letterPhotoWrap) letterPhotoWrap.style.display = 'flex';
    } else if(letterPhotoWrap){
      letterPhotoWrap.style.display = 'none';
    }
    letterModal.classList.add('show');
  }
  function closeLetter(){ letterModal.classList.remove('show'); }
  document.getElementById('letter-close').addEventListener('click', closeLetter);
  letterModal.addEventListener('click', function(e){ if(e.target === letterModal) closeLetter(); });

  scrollContainer.addEventListener('click', function(e){
    if(scrollT >= galleryEnd) return;
    ndc.x = (e.clientX / innerWidth) * 2 - 1;
    ndc.y = -(e.clientY / innerHeight) * 2 + 1;
    raycaster.setFromCamera(ndc, camera);
    var hits = raycaster.intersectObjects(clickableMeshes);
    if(hits.length){
      var hitMesh = hits[0].object;
      var a = artworks.find(function(x){ return x.mesh === hitMesh; });
      if(a) openLetter(a);
    }
  });

  // Hover glow
  var hovered = null;
  scrollContainer.addEventListener('mousemove', function(e){
    if(scrollT >= galleryEnd){
      if(hovered){ setHover(hovered, false); hovered = null; scrollContainer.style.cursor = 'default'; }
      return;
    }
    ndc.x = (e.clientX / innerWidth) * 2 - 1;
    ndc.y = -(e.clientY / innerHeight) * 2 + 1;
    raycaster.setFromCamera(ndc, camera);
    var hits = raycaster.intersectObjects(clickableMeshes);
    var hitA = hits.length ? artworks.find(function(x){ return x.mesh === hits[0].object; }) : null;
    if(hitA !== hovered){
      if(hovered) setHover(hovered, false);
      if(hitA) setHover(hitA, true);
      hovered = hitA;
      scrollContainer.style.cursor = hitA ? 'pointer' : 'default';
    }
  });
  function setHover(a, on){
    a.artMesh.material.emissive.setHex(on ? 0xffdca8 : 0x000000);
    a.artMesh.material.emissiveIntensity = on ? 0.3 : 0;
    a.spot.intensity = on ? 2.3 : 1.5;
  }

  function nearestArtwork(z){
    var best=null, bd=999;
    artworks.forEach(function(a){ var d=Math.abs(a.z-z); if(d<bd){bd=d;best=a;} });
    return bd < 2.2 ? best : null;
  }

  var answered = false;

  function updateUI(t){
    heroEl.style.opacity = t < 0.05 ? (1 - t/0.05) : 0;
    if(introDone){
      scrollHint.classList.toggle('show', t < 0.04);
    }

    // plaque near artworks
    if(t < galleryEnd){
      var cz = cameraAt(t/galleryEnd*0.9+0.02).p[2];
      var near = nearestArtwork(cz);
      if(near){
        plaqueEl.style.opacity = 1;
        plaqueEl.querySelector('.t').textContent = near.title;
        plaqueEl.querySelector('.a').textContent = (near.artist||near.date) ? (near.artist + ' — ' + near.date) : '';
        plaqueEl.querySelector('.d').textContent = near.desc;
      } else { plaqueEl.style.opacity = 0; }
      tapHint.classList.toggle('show', t > 0.06);
    } else { plaqueEl.style.opacity = 0; tapHint.classList.remove('show'); }

    // black veil
    var veil = 0;
    if(t > blackStart) veil = Math.min((t-blackStart)/(blackEnd-blackStart), 1);
    if(t > 0.995) veil = 1;
    veilEl.style.opacity = veil;
    wrap.style.opacity = 1 - veil*0.98;

    // message layer
    var msgActive = t > blackEnd - 0.01;
    msgLayer.style.opacity = msgActive ? 1 : 0;
    lines.forEach(function(el, i){
      var w = msgWindows[i];
      el.classList.toggle('show', t >= w[0]);
    });
    questionEl.classList.toggle('show', t >= questionAt);
    buttonsEl.classList.toggle('show', t >= buttonsAt && !answered);
    if(answered){ buttonsEl.classList.remove('show'); }
  }

  // ---------- Celebration ----------
  function celebrate(){
    if(answered) return;
    answered = true;
    buttonsEl.classList.remove('show');
    var pc = document.getElementById('particles');
    var syms = ['✦','♥','✧','●'];
    for(var i=0;i<50;i++){
      (function(i){
        var el = document.createElement('div');
        el.className = 'p';
        el.textContent = syms[i%syms.length];
        el.style.left = (45+Math.random()*10) + '%';
        el.style.top = '55%';
        el.style.color = i%2? '#c9a86a':'#e8b4a0';
        pc.appendChild(el);
        var dx = (Math.random()-0.5)*70, dy = -(Math.random()*60+30);
        setTimeout(function(){
          el.style.transition = 'transform 1.8s ease-out, opacity 1.8s ease-out';
          el.style.opacity = '1';
          el.style.transform = 'translate('+dx+'vw,'+dy+'vh) scale('+(0.8+Math.random()*0.8)+')';
          setTimeout(function(){ el.style.opacity='0'; }, 1400);
        }, i*18);
      })(i);
    }
    document.body.style.background = 'linear-gradient(180deg,#1a120a,#0a0908)';
    setTimeout(function(){ finalMsgEl.classList.add('show'); }, 900);
  }
  document.getElementById('btnYes').addEventListener('click', celebrate);
  document.getElementById('btnOf').addEventListener('click', celebrate);

  // ---------- Animate ----------
  function animate(){
    requestAnimationFrame(animate);
    scrollT += (targetT - scrollT) * 0.08;
    var camT = Math.min(scrollT / galleryEnd, 1) * 0.98 + 0.01;
    var cam = cameraAt(Math.min(camT,1));
    camera.position.set(cam.p[0], cam.p[1], cam.p[2]);
    camera.lookAt(cam.l[0], cam.l[1], cam.l[2]);
    updateUI(scrollT);
    renderer.render(scene, camera);
  }
  animate();
  startIntro();
})();